items:{
sealed_note:item('fact','The unsigned appointment','Thư hẹn không ký tên','OBSERVATION · A visitor requests a private meeting at eight. The note asks you to accept a covered face. No sender is named.','QUAN SÁT · Một vị khách xin gặp riêng lúc tám giờ và đề nghị bạn chấp nhận việc che mặt. Thư không ghi tên người gửi.'),
watermark:item('fact',"A paper maker’s mark",'Dấu của nhà sản xuất giấy',"OBSERVATION · A watermark names a Varenne mill. This identifies the paper’s maker, not its writer.",'QUAN SÁT · Hình chìm ghi tên xưởng giấy ở Varenne. Dấu này xác định nơi sản xuất giấy, không xác định người viết.'),
press_cutting:item('fact',"Sunday’s announcement",'Thông báo vào Chủ nhật','DOCUMENT · A newspaper says the marriage alliance of Varenne and Norland will be announced on Sunday.','VĂN BẢN · Báo đưa tin hôn ước giữa hoàng gia Varenne và Norland sẽ được công bố vào Chủ nhật.'),
portrait_claim:item('testimony',"The client’s accusation",'Lời buộc tội của khách hàng',"TESTIMONY · Matthias calls a photograph of himself with Celia Voss ‘stolen’. You have not seen the photograph.",'LỜI KHAI · Matthias nói bức ảnh chụp ông cùng Celia Voss đã “bị đánh cắp”. Bạn chưa nhìn thấy bức ảnh.'),
gift_admission:item('testimony','A gift, by his own account','Món quà theo chính lời ông ta','TESTIMONY · Matthias says he gave Celia the photograph in its silver frame. He has described no later theft.','LỜI KHAI · Matthias nói chính ông tặng Celia bức ảnh trong khung bạc. Ông chưa kể về vụ trộm nào xảy ra sau đó.'),
warning_words:item('testimony','The warning he remembers','Lời cảnh báo ông ta nhớ',"TESTIMONY · Matthias recalls: ‘If your men trouble me again, your future family shall hear from me.’ He brought no written message.",'LỜI KHAI · Matthias nhớ lời cảnh báo: “Nếu người của ngài còn quấy rầy tôi, gia đình vợ tương lai của ngài sẽ được nghe chuyện từ tôi.” Ông không mang theo thư từ nào.'),
prior_searches:item('testimony','Earlier attempts','Những lần tìm kiếm trước',"TESTIMONY · Matthias paid men to search Celia’s luggage and home. He admits both attempts failed.",'LỜI KHAI · Matthias thuê người lục hành lý và nhà Celia. Ông thừa nhận cả hai lần đều thất bại.'),
wren_address:item('testimony','Wren House','Nhà Wren',"TESTIMONY · Matthias gives Celia’s address as Wren House, Alder Lane. The visit can verify the address, not his accusation.",'LỜI KHAI · Matthias cho biết Celia ở nhà Wren, ngõ Alder. Đến đó có thể xác minh địa chỉ, không thể tự động xác minh lời buộc tội của ông.'),
disputed_claim:item('inference','An accusation to verify','Lời buộc tội cần xác minh',"SUPPORTED INFERENCE · His gift admission does not support his claim of theft. Celia’s intentions and the photograph’s present location remain unknown.",'SUY LUẬN CÓ CĂN CỨ · Việc ông thừa nhận đã tặng ảnh không củng cố lời buộc tội trộm cắp. Ý định của Celia và nơi cất ảnh hiện nay vẫn chưa rõ.'),
boundary:item('fact','Written limits','Giới hạn bằng văn bản',"DOCUMENT · Matthias signs your terms: establish the facts first; no entry to Celia’s home without her permission.",'VĂN BẢN · Matthias ký điều kiện của bạn: trước hết xác minh sự việc; không vào nhà Celia nếu cô chưa cho phép.'),
visitor_observed:item('fact','A visitor at 9:10','Vị khách lúc 9 giờ 10','OBSERVATION · A man leaves Wren House at 9:10 p.m. A woman hands him gloves. Their names and relationship are not established.','QUAN SÁT · Một người đàn ông rời nhà Wren lúc 9 giờ 10 tối. Một phụ nữ đưa găng tay cho anh ta. Chưa xác định tên hay quan hệ giữa họ.'),
witness_habit:item('testimony',"Finn’s account",'Lời kể của Finn','TESTIMONY · Finn says Celia usually goes out at five in the afternoon. A gentleman has visited several times. Neither claim is verified.','LỜI KHAI · Finn nói Celia thường ra ngoài lúc năm giờ chiều. Một người đàn ông đã đến thăm vài lần. Chưa điều nào được xác minh.'),
witness_intrusion:item('testimony','A broken latch','Chốt cửa bị hỏng',"TESTIMONY · Finn says Celia had her side-door latch repaired after strangers entered. He did not see who broke it.",'LỜI KHAI · Finn nói Celia cho sửa chốt cửa bên sau khi người lạ vào nhà. Anh không thấy ai làm hỏng chốt.'),
invitation:item('fact','An answer in blue ink','Lời đáp bằng mực xanh',"DOCUMENT · A note signed C. Voss invites Adrian Vale to return at five tomorrow. It adds: ‘Come to ask, not to collect.’",'VĂN BẢN · Thư ký tên C. Voss mời Adrian Vale trở lại lúc năm giờ ngày mai. Thư còn ghi: “Hãy đến để hỏi, đừng đến để lấy.”')
},
